(function(root){
  'use strict';
  const M=root.WasteModel; if(!M) throw new Error('WasteModel 尚未載入');
  const L=root.WasteLaw; if(!L) throw new Error('WasteLaw 尚未載入');
  let state=M.createState(); L.ensureState(state);
  let host=null;
  const app=()=>host||document.getElementById('app');
  const esc=(s='')=>String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  const val=(id)=>document.getElementById(id)?.value?.trim()||'';
  const checked=(name)=>[...document.querySelectorAll(`input[name="${name}"]:checked`)].map(x=>x.value);
  const one=(name)=>document.querySelector(`input[name="${name}"]:checked`)?.value||'';
  const options=(items,current='',blank='請選擇')=>`<option value="">${esc(blank)}</option>${items.map(x=>{const a=Array.isArray(x)?x:[x,x];return `<option value="${esc(a[0])}" ${current===a[0]?'selected':''}>${esc(a[1])}</option>`}).join('')}`;
  const checks=(name,items,selected=[])=>`<div class="check-grid">${items.map(x=>{const a=Array.isArray(x)?x:[x,x];return `<label class="check"><input type="checkbox" name="${name}" value="${esc(a[0])}" ${selected.includes(a[0])?'checked':''}><span>${esc(a[1])}</span></label>`}).join('')}</div>`;
  const radios=(name,items,current='')=>`<div class="choice-row">${items.map(x=>{const a=Array.isArray(x)?x:[x,x];return `<label class="choice"><input type="radio" name="${name}" value="${esc(a[0])}" ${current===a[0]?'checked':''}><span>${esc(a[1])}</span></label>`}).join('')}</div>`;
  const subjName=id=>M.labelById(state.subjects,id,['name']);
  const batchName=id=>M.labelById(state.batches,id,['label','materialKind']);
  const placeName=id=>M.labelById(state.places,id,['name']);
  const placeOptionLabel=p=>{const owner=subjName(p?.subjectId);return `${p?.name||p?.id||'未命名地點'}${owner?`｜${owner}`:''}`;};
  const placeFlowName=id=>{const p=state.places.find(x=>x.id===id);return p?placeOptionLabel(p):'';};
  const vehName=id=>M.labelById(state.vehicles,id,['plate']);
  const fieldLabels={label:'批次名稱',materialKind:'物質',appearance:'外觀／狀態',quantity:'數量',quantityUnit:'數量單位',quantitySource:'數量來源',originSubjectId:'舊版原始產源主體',originPlaceId:'舊版原始產源地點',process:'產生活動／製程',generationContext:'產生活動／情境',wasteIdentity:'廢棄物身分',sourceStatus:'來源狀態',classification:'一般／事業分類',detailClassification:'細部分類',wasteCode:'廢棄物代碼',codeReview:'代碼核對',claimUse:'聲稱用途',documentUse:'文件用途',actualUse:'實際用途',notes:'補充',plate:'車牌',vehicleType:'車種',ownerText:'車主／所屬公司',marking:'車身標示',source:'資料來源',name:'地點名稱',address:'地址／位置',roles:'地點角色',subjectId:'關聯主體',landRelation:'土地關係',batchId:'關聯批次',placeId:'產生來源地點',status:'確認狀態',generationActivity:'產生情境',evidence:'資料來源',basisText:'依據／線索',recordedAt:'記錄時間',occurrenceTime:'發生時間',locationText:'位置描述',phenomena:'環境現象',media:'受影響位置／介質',extentText:'範圍／程度',extentBasis:'範圍資料性質',currentStatus:'當下狀態',sourceDetail:'資料來源補充',batchIds:'關聯批次',previousObservationId:'前次觀察'};
  function displayRevisionValue(field,value){if(Array.isArray(value))return value.length?value.join('、'):'未填';if(field==='originSubjectId')return subjName(value)||value||'未填';if(field==='originPlaceId')return placeName(value)||value||'未填';return String(value??'').trim()||'未填';}
  function renderHistory(item){const h=Array.isArray(item?.history)?item.history:[];if(!h.length)return '';return `<details class="revision-history"><summary>修改紀錄（${h.length}）</summary>${h.map(r=>`<div class="muted small">第 ${r.seq} 次｜${esc(r.type||'變更')}：${r.changes.map(c=>`${esc(fieldLabels[c.field]||c.field)}「${esc(displayRevisionValue(c.field,c.from))}」→「${esc(displayRevisionValue(c.field,c.to))}」`).join('；')}</div>`).join('')}</details>`;}
  function setView(view){state.view=view;render();root.scrollTo?.({top:0,behavior:'smooth'});}
  function title(){const m=root.INSPECTION_APP_META,el=document.getElementById('appTitle');if(el)el.textContent=m?.label||'稽查助手－廢棄物 V0.1';}
  function hasData(){return !!(state.entryMode||state.subjects.length||state.batches.length||state.environmentObservations?.length||state.producerRelations?.length||state.events.length||state.vehicles.length||state.places.length||state.documents.length||state.flows.length||state.questions.length||state.doubts.length||state.assessments.length||state.sourceTrace.status||state.draftText);}
  function render(){title();M.ensureState(state);L.ensureState(state);if(state.view==='home')renderHome();else if(state.view==='unknown')renderUnknown();else if(state.view==='known')renderKnown();else if(state.view==='law')renderLaw();else if(state.view==='summary')renderSummary();else renderHome();}

  function commonTools(){
    return `<div class="actions-sticky"><button class="secondary" id="toolHome">首頁</button><button class="secondary" id="toolLaw" ${hasData()?'':'disabled'}>法規導航</button><button class="secondary" id="toolSummary" ${hasData()?'':'disabled'}>整理目前內容／結束本次查核</button><button class="ghost" id="toolExport" ${hasData()?'':'disabled'}>匯出案件 JSON</button><button class="ghost" id="toolImport">匯入案件 JSON</button><input type="file" id="importFile" accept="application/json,.json" hidden><button class="danger" id="toolReset">清空本次資料</button></div>`;
  }
  function bindTools(){
    document.getElementById('toolHome')?.addEventListener('click',()=>setView('home'));
    document.getElementById('toolLaw')?.addEventListener('click',()=>setView('law'));
    document.getElementById('toolSummary')?.addEventListener('click',()=>setView('summary'));
    document.getElementById('toolReset')?.addEventListener('click',()=>{if(confirm('確定清空本次頁面中的廢棄物測試資料？')){state=M.createState();render();}});
    document.getElementById('toolExport')?.addEventListener('click',()=>{
      const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='waste-case-v01.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);
    });
    document.getElementById('toolImport')?.addEventListener('click',()=>document.getElementById('importFile').click());
    document.getElementById('lawMiniOpen')?.addEventListener('click',()=>setView('law'));
    document.getElementById('clearLawNavHint')?.addEventListener('click',()=>{state.law.navHint=null;render();});
    document.querySelectorAll('[data-open-law]').forEach(b=>b.onclick=()=>setView('law'));
    document.getElementById('importFile')?.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{const obj=JSON.parse(await f.text());if(!M.validateImport(obj))throw new Error('檔案格式或 provenance 不符');state=obj;M.ensureState(state);L.ensureState(state);render();}catch(err){alert(`匯入失敗：${err.message}`);}});
  }

  function renderHome(){
    app().innerHTML=`
      <section class="hero"><h2>廢棄物現場稽查 V0.1.5</h2><p>先建立共用事實：人、物、地、事件與環境觀察；廢棄物批次再依產生者／產生情境整理一般或事業廢棄物分類。</p><span class="pill">環境觀察與廢棄物／物質線平行；系統只提示，不替稽查員補事實或指定責任</span></section>
      <section class="grid2">
        <article class="card entry" id="enterUnknown"><div class="big">⌕</div><h3>來源待查</h3><p>不知道誰排出、從哪裡來。先保全會消失的事實，再認物、追來源。</p><p class="muted">現場事實保全 → 認物／環境觀察 → 來源線索 → 找到來源後匯入對象查核。</p><button>開始來源待查</button></article>
        <article class="card entry" id="enterKnown"><div class="big">▣</div><h3>稽查對象已知</h3><p>已知事業、行為人、地主、清運者、處理／再利用場所等。</p><p class="muted">認主體 → 認物／環境觀察 → 認廢 → 產生者／分類 → 事件／流向 → 資格／文件 → 疑點。</p><button>開始對象查核</button></article>
      </section>
      <section class="card"><h3>設計原則</h3><div class="grid2"><div class="summary-block"><strong>客觀事實 ≠ 現場研判</strong><div class="muted">卸載、推平是客觀動作；「疑似回填」是研判，兩者分開。</div></div><div class="summary-block"><strong>提示 ≠ 案件資料</strong><div class="muted">只有稽查員主動建立疑點、待確認或研判後，才進正式案件資料。</div></div></div></section>
      ${commonTools()}`;
    document.getElementById('enterUnknown').onclick=()=>{state.entryMode='unknown';setView('unknown');};
    document.getElementById('enterKnown').onclick=()=>{state.entryMode='known';setView('known');};
    bindTools();
  }

  function renderUnknown(){
    const s=state.sourceTrace;
    app().innerHTML=`
      <div class="section-title"><div><h2>來源待查</h2><p>第一優先是留下可能消失的現場事實；不因來源不明就推定任何人為行為人。</p></div><button class="secondary" id="toKnown">轉入對象查核</button></div>
      <div class="stepbar"><span class="step ${preservationDone()?'done':'active'}">1 事實保全</span><span class="step ${state.batches.length||state.environmentObservations.length?'done':'active'}">2 物質／環境</span><span class="step ${s.status?'done':'active'}">3 追來源</span><span class="step">4 可能後續方向</span></div>
      <section class="card"><h3>1｜現場事實保全</h3><p class="muted">固定五類：人、車／機具、物、行為、位置／時間。此區只寫當下直接可記錄的內容。</p>
        ${presField('人','presPeople',state.preservation.people,'例如：現場 2 人，其中 1 人操作挖土機')}
        ${presField('車／機具','presVehicles',state.preservation.vehicles,'例如：ABC-1234 貨車、挖土機 1 部')}
        ${presField('物','presMaterials',state.preservation.materials,'例如：木材、塑膠、磚瓦混合物約 1 車')}
        ${presField('行為','presActions',state.preservation.actions,'例如：車輛正在卸載；挖土機推平')}
        ${presField('位置／時間','presPlaceTime',state.preservation.placeTime,'例如：09:40，土地北側')}
        <div class="btn-row"><button id="savePres">更新現場保全</button></div>
      </section>
      <section class="card"><div class="record-head"><div><h3>2A｜廢棄物／物質：物質批次</h3><p class="muted">先做到現場可辨識層級；物質批次與環境觀察可各自獨立建立。</p></div><button id="addBatchUnknown">＋新增批次</button></div>${renderBatchesCompact()}</section>
      <section class="card"><div class="record-head"><div><h3>2B｜環境狀態／污染現象：環境觀察</h3><p class="muted">共用第一級事實；不知道來源、行為人或物質批次，也可先記現場所見。</p></div><div class="btn-row"><button id="addEnvironmentUnknown">＋新增環境觀察</button><button class="secondary" id="addPlaceUnknown">＋地點</button></div></div>${renderEnvironmentObservations()}${renderEnvironmentReview()}${renderCrossModuleHints()}</section>
      <section class="card"><h3>3｜追來源</h3><label class="field"><span class="label">來源追查狀態</span><select id="sourceStatus">${options(M.sourceStates,s.status)}</select></label>
        <label class="field"><span class="label">來源線索（可複選）</span>${checks('sourceClues',['車牌','包裝標示','文件','收據','地址','公司名稱','姓名／電話','物質特性','監視器','附近人員陳述','地主陳述','其他'],s.clues)}</label>
        <label class="field"><span class="label">追查補充</span><textarea id="sourceNotes" placeholder="只記查了什麼、查到什麼；線索不等於來源已確認。">${esc(s.notes)}</textarea></label>
        <div class="btn-row"><button id="saveSource">更新來源追查</button></div>${renderSourceLeads()}
      </section>
      ${renderSourceOutcome()}
      ${renderLawMiniBar()}
      ${renderSystemHints()}
      ${commonTools()}`;
    document.getElementById('savePres').onclick=()=>{state.preservation={people:val('presPeople'),vehicles:val('presVehicles'),materials:val('presMaterials'),actions:val('presActions'),placeTime:val('presPlaceTime')};render();};
    document.getElementById('addBatchUnknown').onclick=()=>batchDialog();
    document.getElementById('addEnvironmentUnknown').onclick=()=>environmentObservationDialog();
    document.getElementById('addPlaceUnknown').onclick=()=>placeDialog();
    bindEnvironmentReview();
    bindCrossModuleHints();
    document.getElementById('saveSource').onclick=()=>{s.status=val('sourceStatus');s.clues=checked('sourceClues');s.notes=val('sourceNotes');if(s.status!=='來源已確認'){s.confirmedSubjectId='';s.handoffCompleted=false;}render();};
    document.getElementById('confirmedSourceSubject')?.addEventListener('change',e=>{s.confirmedSubjectId=e.target.value;const go=document.getElementById('sourceToKnown');if(go)go.disabled=!M.canSourceHandoff(state);});
    document.getElementById('addConfirmedSourceSubject')?.addEventListener('click',()=>subjectDialog(subject=>{s.confirmedSubjectId=subject.id;}));
    document.getElementById('sourceToKnown')?.addEventListener('click',()=>{s.confirmedSubjectId=val('confirmedSourceSubject');if(!M.handoffConfirmedSource(state)){alert('請先指定或建立已確認的來源主體。');return;}setView('known');});
    document.getElementById('sourceUnresolvedSummary')?.addEventListener('click',()=>setView('summary'));
    document.getElementById('toKnown').onclick=()=>{state.entryMode='known';setView('known');};
    bindRecordButtons();bindHintButtons();bindTools();
  }
  function presField(label,id,value,ph){return `<label class="field"><span class="label">${label}</span><input id="${id}" value="${esc(value)}" placeholder="${esc(ph)}"></label>`;}
  function preservationDone(){return Object.values(state.preservation).some(Boolean);}

  function renderSourceOutcome(){
    const s=state.sourceTrace;
    if(s.status==='來源已確認'){
      const ready=M.canSourceHandoff(state);
      return `<section class="card source-outcome"><h3>4｜來源已確認：銜接對象查核</h3><p>先指定這次追查所確認的來源主體，再把前段已建立的批次、事件、人物、車輛、地點與流向原樣帶入主流程。</p><div class="notice info">「來源主體」不等於自動認定為原始產生者、排出者或違規行為人；進入主流程後再確認其本案角色。</div><label class="field"><span class="label">已確認來源主體</span><select id="confirmedSourceSubject">${options(state.subjects.map(x=>[x.id,x.name]),s.confirmedSubjectId,'請指定來源主體')}</select></label><div class="btn-row"><button class="secondary" id="addConfirmedSourceSubject">＋建立來源主體</button><button class="good" id="sourceToKnown" ${ready?'':'disabled'}>確認來源並進入對象查核</button></div></section>`;
    }
    if(s.status==='本次無法確認來源'){
      return `<section class="card source-outcome"><h3>4｜本次無法確認來源</h3><p>查源支線可在此收斂。既有客觀事實全部保留，不強迫建立一個未確認的來源。</p><div class="notice warn">下方只會顯示「可能後續方向」，例如符合前提時提示第 11 條；是否深入仍由稽查員決定。</div><div class="btn-row"><button id="sourceUnresolvedSummary">整理目前內容／結束本次查核</button></div></section>`;
    }
    return '';
  }

  function renderKnown(){
    state.entryMode='known';
    app().innerHTML=`
      <div class="section-title"><div><h2>稽查對象已知</h2><p>先建立主體與物質，再用事件把人、物、車、地點串起來；法規導航依既有事實提示下一步，但不取代事實紀錄。</p></div><button class="secondary" id="backUnknown">切回來源待查</button></div>
      ${renderLawNavHint()}
      ${state.sourceTrace?.handoffCompleted?`<section class="card"><h3>由「來源待查」轉入</h3><div class="notice good">已確認來源主體：<strong>${esc(subjName(state.sourceTrace.confirmedSubjectId)||'未命名主體')}</strong>。前段查源資料已保留；下一步請確認該主體在本案中的角色，再繼續認廢、事件與流向查核。</div></section>`:''}
      <div class="stepbar"><span class="step ${state.subjects.length?'done':'active'}">1 主體</span><span class="step ${state.batches.length||state.environmentObservations.length?'done':'active'}">2 物質／環境</span><span class="step ${state.producerRelations.length?'done':'active'}">3 產生者／分類</span><span class="step ${state.events.length?'done':'active'}">4 事件</span><span class="step ${state.flows.length?'done':'active'}">5 流向</span><span class="step ${state.documents.length?'done':'active'}">6 核對</span></div>
      ${renderLawMiniBar()}
      <section class="card" id="known-subjects"><div class="record-head"><div><h3>1｜主體角色</h3><p class="muted">同一主體可以一人多角；產生者仍以批次的「產生者關係」另行確認。</p></div><button id="addSubject">＋新增主體</button></div>${renderSubjects()}</section>
      <section class="card" id="known-environment"><div class="record-head"><div><h3>2A｜環境觀察（共用事實）</h3><p class="muted">環境現象不必先綁定廢棄物；可獨立建立，再與批次、事件、人、車或來源線索關聯。</p></div><div class="btn-row"><button id="addEnvironment">＋新增環境觀察</button><button class="secondary" id="addPlaceEnvironment">＋地點</button></div></div>${renderEnvironmentObservations()}${renderEnvironmentReview()}${renderCrossModuleHints()}</section>
      <section class="card" id="known-batches"><div class="record-head"><div><h3>2B｜物質批次、認廢與產生者</h3><p class="muted">一般／事業分類以該批次的產生者及產生情境為主要判斷基礎；未知不會卡住其他事實紀錄。</p></div><button id="addBatch">＋新增批次</button></div>${renderBatchesFull()}</section>
      <section class="card" id="known-events"><div class="record-head"><div><h3>4｜客觀事件</h3><p class="muted">每筆事件記「時間＋誰／車＋哪批物＋做了什麼＋在哪裡」。未知欄位可留白。</p></div><div class="btn-row"><button id="addEvent">＋新增事件</button><button class="secondary" id="addPlace">＋地點</button><button class="secondary" id="addVehicle">＋車輛</button></div></div>${renderEventEntities()}${renderTimeline()}</section>
      <section class="card" id="known-flows"><div class="record-head"><div><h3>5｜物流向</h3><p class="muted">去向與用途分開；原始產源與本段來源也分開。</p></div><button id="addFlow">＋新增流向</button></div>${renderFlows()}</section>
      <section class="card" id="known-documents"><div class="record-head"><div><h3>6｜資格／文件簡易核對</h3><p class="muted">系統不持有許可或申報資料；只記錄稽查員自行外部核對後的結果。</p></div><button id="addDocument">＋新增核對</button></div>${renderDocuments()}</section>
      ${renderSystemHints()}
      ${renderGapHints()}
      <section class="grid2"><div class="card"><div class="record-head"><div><h3>疑點</h3><p class="muted">疑點先查證；不直接升格異常。</p></div><button id="addDoubt">＋新增</button></div>${renderDoubts()}</div><div class="card"><div class="record-head"><div><h3>待確認事項</h3><p class="muted">系統缺漏提示不會自動寫入；只有你加入後才是案件資料。</p></div><button id="addPending">＋新增</button></div>${renderPending()}</div></section>
      ${commonTools()}`;
    document.getElementById('backUnknown').onclick=()=>{state.entryMode='unknown';setView('unknown');};
    document.getElementById('addSubject').onclick=()=>subjectDialog();
    document.getElementById('addBatch').onclick=()=>batchDialog();
    document.getElementById('addEnvironment').onclick=()=>environmentObservationDialog();
    document.getElementById('addPlaceEnvironment').onclick=()=>placeDialog();
    bindEnvironmentReview();
    bindCrossModuleHints();
    document.getElementById('addEvent').onclick=()=>eventDialog();
    document.getElementById('addPlace').onclick=()=>placeDialog();
    document.getElementById('addVehicle').onclick=()=>vehicleDialog();
    document.getElementById('addFlow').onclick=()=>flowDialog();
    document.getElementById('addDocument').onclick=()=>documentDialog();
    document.getElementById('addDoubt').onclick=()=>doubtDialog();
    document.getElementById('addPending').onclick=()=>pendingDialog();
    bindRecordButtons();bindHintButtons();bindGapButtons();bindTools();
  }

  function renderLawMiniBar(){
    if(!hasData())return '';
    const snap=L.lawSnapshot(state);
    const active=snap.suggestions.filter(x=>!state.assessments.some(a=>a.suggestionKey===x.key)).length;
    return `<section class="law-mini"><div><strong>現場法規導航</strong><span>可能方向 ${active}｜已建立查核 ${snap.assessments.length}｜必要待確認 ${snap.pending}</span></div><button class="secondary" id="lawMiniOpen">查看</button></section>`;
  }
  function renderLawNavHint(){
    const h=state.law?.navHint;if(!h)return '';
    return `<div class="notice info law-nav-hint"><strong>本次查核目的：</strong>${esc(h.text||'補充相關事實')}<button class="ghost" id="clearLawNavHint">清除提示</button><div class="muted small">此文字只作操作導航，不會寫入事件、陳述、摘要事實或稽查紀錄草稿。</div></div>`;
  }
  function lawRuleStatusBadge(status){if(status==='implemented')return '<span class="chip good">要件規則已建立</span>';if(status==='future')return '<span class="chip warn">未來生效</span>';if(status==='reference')return '<span class="chip">條文索引</span>';return '<span class="chip warn">規則待擴充</span>';}
  function renderLawSuggestions(){
    const existing=new Set(state.assessments.map(a=>a.suggestionKey).filter(Boolean));
    const list=L.detectDirections(state).filter(x=>!existing.has(x.key));
    if(!list.length)return '<div class="empty">目前沒有新的系統法規方向提示；仍可由稽查員自行新增方向。</div>';
    return list.map(x=>`<article class="subcard law-suggestion"><div class="record-head"><div><h4>${esc(x.title)}</h4><div class="chips"><span class="chip blue">系統提示</span>${lawRuleStatusBadge(x.status)}</div></div><button class="ghost" data-law-dismiss="${esc(x.key)}">暫不顯示</button></div><div class="muted">提示原因：${esc(x.reason)}</div>${x.batchId?`<div class="muted">主要批次候選：${esc(batchName(x.batchId)||x.batchId)}</div>`:''}<div class="btn-row"><button data-law-start="${esc(x.key)}">進一步查核</button></div></article>`).join('');
  }
  function reqKindTitle(kind){return ({premise:'法律前提',fact:'事實要件',exception:'例外／排除條件',supplement:'補強事項'})[kind]||'其他';}
  function howToHtml(req){
    const h=req.howTo||{}, labels={observe:'現場觀察',ask:'詢問／陳述',documents:'文件',followup:'外部資料／後續查證',other:'影像／其他資料'};
    const parts=Object.entries(labels).filter(([k])=>h[k]?.length).map(([k,label])=>`<div class="howto-group"><strong>${label}</strong><ul>${h[k].map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`).join('');
    return parts?`<details class="howto"><summary>如何確認</summary>${parts}</details>`:'';
  }
  function linkListHtml(a,req,side){
    const key=side==='counter'?'counterLinks':'supportLinks', title=side==='counter'?'相反／不支持事實':'支持事實';
    const ids=a[key]?.[req.id]||[];
    return `<div class="law-links"><strong>${title}</strong>${ids.length?ids.map(id=>`<span class="law-link-chip">${esc(L.recordLabel(state,id))}<button class="ghost tiny" data-law-unlink="${a.id}" data-req="${req.id}" data-record="${id}" data-side="${side}">×</button></span>`).join(''):'<span class="muted">尚未引用</span>'}</div>`;
  }
  function candidatePickerHtml(a,req){
    const facts=L.candidateFacts(state,a,req), used=new Set([...(a.supportLinks?.[req.id]||[]),...(a.counterLinks?.[req.id]||[])]), available=facts.filter(x=>!used.has(x.id));
    if(!available.length)return '<div class="muted small">目前沒有新的候選相關資料；可由下方「去補事實」返回原資料層。</div>';
    return `<div class="law-candidate"><select id="lawCand-${a.id}-${req.id}">${options(available.map(x=>[x.id,x.label]),'','選擇候選資料')}</select><button class="secondary" data-law-link="${a.id}" data-req="${req.id}" data-side="support">列為支持</button><button class="ghost" data-law-link="${a.id}" data-req="${req.id}" data-side="counter">列為相反</button></div>`;
  }
  function renderRequirement(a,req){
    const current=a.requirementStates?.[req.id]||'尚有要件待確認';
    const affect=req.required&&req.kind!=='supplement'&&req.kind!=='exception';
    return `<article class="requirement ${req.kind}"><div class="record-head"><div><strong>${esc(req.label)}</strong><div class="chips"><span class="chip">${esc(reqKindTitle(req.kind))}</span><span class="chip ${req.onsite==='現場查核優先'?'warn':''}">${esc(req.onsite||'一般現場確認')}</span>${affect?'<span class="chip blue">影響整體研判</span>':''}</div></div><select class="req-state" data-law-req-state="${a.id}" data-req="${req.id}">${options(L.requirementStates,current,'請選擇狀態')}</select></div>${req.warning?`<div class="notice warn compact">${esc(req.warning)}</div>`:''}${linkListHtml(a,req,'support')}${linkListHtml(a,req,'counter')}${candidatePickerHtml(a,req)}${howToHtml(req)}<div class="btn-row"><button class="secondary" data-law-goto="${a.id}" data-req="${req.id}" data-target="${esc(req.target||'event')}">去補事實</button></div></article>`;
  }
  function renderAssessment(a){
    const {rule,resolved,requirements}=L.getRequirements(state,a), active=L.triggerIsActive(state,a), overview=L.behaviorOverview(state,a), facts=L.allRelatedFacts(state,a);
    const basis=resolved.version?.legalBasis||rule.legalBasis||[];
    const grouped=['premise','fact','exception','supplement'].map(kind=>{const rs=requirements.filter(r=>r.kind===kind);return rs.length?`<section class="law-req-group"><h4>${reqKindTitle(kind)}</h4>${rs.map(r=>renderRequirement(a,r)).join('')}</section>`:''}).join('');
    return `<article class="card law-assessment" data-assessment="${a.id}"><div class="record-head"><div><h3>${esc(a.direction)}</h3><div class="chips"><span class="chip ${a.source==='system'?'blue':''}">${a.source==='system'?'系統提示':'稽查員新增'}</span><span class="chip ${a.legalState==='構成要件事實已完整'?'good':a.legalState==='目前不支持'?'':'warn'}">${esc(a.legalState)}</span>${lawRuleStatusBadge(rule.status)}</div></div><button class="danger" data-law-delete="${a.id}">刪除查核</button></div>
      ${a.source==='system'&&!active?'<div class="notice warn">目前已無原始提示依據；本查核歷程仍保留，請由稽查員決定是否繼續。</div>':''}
      ${a.triggerReason?`<div class="muted">原始提示原因：${esc(a.triggerReason)}</div>`:''}
      <div class="grid3 law-core"><label class="field"><span class="label">主要物質批次</span><select data-law-core="batch" data-id="${a.id}">${options(state.batches.map(b=>[b.id,b.label||b.materialKind||b.id]),a.primaryBatchId,'無／尚未指定')}</select></label><label class="field"><span class="label">判斷主體</span><select data-law-core="subject" data-id="${a.id}">${options(state.subjects.map(s=>[s.id,s.name||s.id]),a.subjectId,'無／尚未指定')}</select></label><label class="field"><span class="label">角色</span><select data-law-core="role" data-id="${a.id}">${options(M.roles,a.role,'尚未指定')}</select></label></div>
      <div class="grid3"><label class="field"><span class="label">行為日期</span><input type="date" data-law-core="date" data-id="${a.id}" value="${esc(a.behaviorDate||'')}"><span class="hint">用行為日期選法規版本，不用今天日期。</span></label><label class="field"><span class="label">查核進度</span><select data-law-progress="${a.id}">${options(L.progressStates,a.progress)}</select></label><label class="field"><span class="label">暫不深入原因</span><input data-law-pause="${a.id}" value="${esc(a.pauseReason||'')}" placeholder="本次資料不足／後續另查等"></label></div>
      <div class="law-version ${resolved.status==='ok'?'ok':'pending'}"><strong>法規版本：</strong>${resolved.status==='ok'?esc(resolved.version.id):esc(resolved.message)}${basis.length?`<div class="muted">依據：${basis.map(esc).join('、')}</div>`:''}${rule.penaltyRefs?.length?`<div class="muted">處罰／後續關聯：${rule.penaltyRefs.map(esc).join('、')}</div>`:''}<div class="muted">規則包：${esc(a.rulePackVersion)}${a.ruleVersionId?`｜Rule：${esc(a.ruleVersionId)}`:''}</div></div>
      ${overview?`<div class="notice info compact"><strong>行為概況</strong><br>${esc(overview)} <span class="muted">只做機械式事件整理，不加入違法或評價性文字。</span></div>`:''}
      <details class="related-facts"><summary>目前相關事實 ${facts.length} 筆</summary>${facts.length?facts.map(x=>`<div class="muted small">${esc(x.label)}</div>`).join(''):'<div class="empty compact">尚無相關事實。</div>'}</details>
      ${resolved.status==='ok'?grouped:`<div class="notice warn">${esc(rule.note||resolved.message||'目前無可載入的構成要件版本。')}</div>`}
      <label class="field"><span class="label">法規查核補充</span><textarea data-law-notes="${a.id}">${esc(a.notes||'')}</textarea></label>
    </article>`;
  }
  function renderDepartureCheckBlock(){
    const d=L.departureCheck(state);
    if(!state.assessments.length)return '';
    return `<section class="card"><div class="record-head"><div><h3>離場前檢查</h3><p class="muted">跨法規方向去除重複，只提醒仍適合趁人在現場補查的事項；不強迫完成。</p></div></div>${d.onsite.length?`<div class="departure-list">${d.onsite.map(x=>`<div class="subcard compact"><strong>${esc(x.label)}</strong><span class="chip ${x.onsite==='現場查核優先'?'warn':''}">${esc(x.onsite)}</span></div>`).join('')}</div>`:'<div class="notice good">現場查核已無待補事項。仍可能有後續查證或尚未展開的法規方向。</div>'}${d.follow.length?`<details><summary>後續查證 ${d.follow.length} 項</summary>${d.follow.map(x=>`<div class="muted small">${esc(x.label)}</div>`).join('')}</details>`:''}</section>`;
  }
  function renderRulePackInfo(){
    const st=L.rulePackStatus(),m=st.meta;
    return `<details class="card rule-pack"><summary><strong>法規規則包</strong>｜${esc(m.version||'未知版本')}｜${st.valid?'完整性檢查通過':'完整性檢查失敗'}</summary><div class="grid2"><div><strong>${esc(m.name||'')}</strong><div class="muted">狀態：${esc(m.status||'')}｜最後核對：${esc(m.lastVerifiedAt||'')}｜法規修正：${esc(m.lawAmendedAt||'')}</div><div class="muted">相容程式：${esc(m.compatibleApp||'')}｜全法索引：${st.articleCount||0} 條／次條｜${esc(m.integrityMethod||'')}：${esc(m.checksum||'')}</div></div><div>${st.notices.map(x=>`<div class="muted small">• ${esc(x)}</div>`).join('')}</div></div></details>`;
  }
  function renderArticleCatalog(){
    const list=L.articleCatalog();if(!list.length)return '';
    const chapters=[...new Set(list.map(x=>x.chapter))];
    return `<details class="card law-article-catalog"><summary><strong>廢棄物清理法全條文索引</strong>｜${list.length} 條／次條</summary><p class="muted">已收錄母法全條文索引。現場自動提示只針對有合理事實觸發條件的條文；其他條文仍可在這裡查閱，不會為了「全收錄」而一直跳提示。</p><label class="field"><span class="label">搜尋條號或內容</span><input id="lawArticleSearch" placeholder="例如：27、道路、清理計畫書、再利用"></label>${chapters.map(ch=>`<section class="law-article-chapter"><h4>${esc(ch)}</h4>${list.filter(a=>a.chapter===ch).map(a=>{const dirs=(a.directionIds||[]).map(id=>root.WasteRulePack?.directions?.find(r=>r.id===id)).filter(Boolean);const status=a.status==='deleted'?'<span class="chip">刪除</span>':a.status==='future'?'<span class="chip warn">117/07/15 生效</span>':'<span class="chip good">現行／索引</span>';return `<article class="subcard compact law-article-item" data-article-search="${esc(`${a.article} ${a.summary} ${a.chapter}`)}"><div class="record-head"><div><strong>第 ${esc(a.article)} 條</strong> ${status}<div class="muted">${esc(a.summary)}</div>${a.effectiveNote?`<div class="muted small">${esc(a.effectiveNote)}</div>`:''}</div>${dirs.length?`<div class="btn-row">${dirs.slice(0,4).map(r=>`<button class="ghost" data-article-rule="${esc(r.id)}">建立查核</button>`).join('')}${dirs.length>4?`<span class="muted small">另 ${dirs.length-4} 個子方向可由「稽查員新增方向」選擇</span>`:''}</div>`:''}</div></article>`;}).join('')}</section>`).join('')}</details>`;
  }
  function renderLaw(){
    const snap=L.lawSnapshot(state);
    app().innerHTML=`<div class="section-title"><div><h2>現場法規導航</h2><p>用已建立事實找可能方向、缺漏與下一步；不是正式稽查紀錄，也不直接認定違法。</p></div><div class="btn-row"><button class="secondary" id="lawBackKnown">返回對象查核</button><button class="secondary" id="lawToSummary">現場摘要</button></div></div>
      <section class="summary-grid"><div class="summary-block"><h4>可能方向</h4>${snap.suggestions.length}</div><div class="summary-block"><h4>已建立查核</h4>${snap.assessments.length}</div><div class="summary-block"><h4>必要待確認</h4>${snap.pending}</div><div class="summary-block"><h4>定位</h4>現場導航，不是法律結論</div></section>
      ${renderRulePackInfo()}
      ${renderArticleCatalog()}
      <section class="card"><div class="record-head"><div><h3>可能法規方向</h3><p class="muted">同一組事實可同時提示多個方向；每個方向都有觸發原因。系統提示與稽查員新增並存。</p></div><button id="lawAddManual">＋稽查員新增方向</button></div>${renderLawSuggestions()}</section>
      ${state.assessments.length?`<section><div class="section-title"><div><h2>已建立法規查核</h2><p>每筆固定一個主要批次＋主體／角色＋法規方向；事實可跨方向共用。</p></div></div>${state.assessments.map(renderAssessment).join('')}</section>`:'<section class="card"><div class="empty">尚未建立法規查核。可由上方系統提示按「進一步查核」，或由稽查員自行新增。</div></section>'}
      ${renderDepartureCheckBlock()}
      ${commonTools()}`;
    document.getElementById('lawBackKnown').onclick=()=>setView(state.entryMode==='unknown'?'unknown':'known');
    document.getElementById('lawToSummary').onclick=()=>setView('summary');
    document.getElementById('lawAddManual').onclick=()=>lawCreateDialog();
    bindLawView();bindArticleCatalog();bindTools();
  }
  function bindArticleCatalog(){
    const input=document.getElementById('lawArticleSearch');if(input)input.oninput=()=>{const q=input.value.trim().toLowerCase();document.querySelectorAll('.law-article-item').forEach(el=>{el.style.display=!q||String(el.dataset.articleSearch||'').toLowerCase().includes(q)?'':'none';});};
    document.querySelectorAll('[data-article-rule]').forEach(b=>b.onclick=()=>lawCreateDialog(null,b.dataset.articleRule));
  }
  function lawCreateDialog(suggestion=null,forcedRuleId=''){
    const rules=root.WasteRulePack?.directions||[], defaultRule=forcedRuleId||suggestion?.ruleId||'', defaultBatch=suggestion?.batchId||'';
    dialogShell(suggestion?'建立法規查核':'稽查員新增法規方向',`<div class="notice info">建立的是「查核方向」，不是法律結論。先指定主要批次與主體／角色，後續要件再連回事實。</div><label class="field"><span class="label">法規方向</span><select id="mLawRule">${options(rules.map(r=>[r.id,`${r.title}${r.status==='scaffold'?'（規則待擴充）':r.status==='future'?'（未來生效）':''}`]),defaultRule)}</select></label><div class="grid2"><label class="field"><span class="label">主要物質批次</span><select id="mLawBatch">${options(state.batches.map(b=>[b.id,b.label||b.materialKind||b.id]),defaultBatch,'無／尚未指定')}</select></label><label class="field"><span class="label">判斷主體</span><select id="mLawSubject">${options(state.subjects.map(s=>[s.id,s.name||s.id]),'','無／尚未指定')}</select></label></div><div class="grid2"><label class="field"><span class="label">角色</span><select id="mLawRole">${options(M.roles)}</select></label><label class="field"><span class="label">行為日期</span><input type="date" id="mLawDate"><span class="hint">不確定可先留白；系統會顯示適用版本待確認。</span></label></div>`,()=>{const ruleId=val('mLawRule');if(!ruleId){alert('請選擇法規方向。');return false;}L.createAssessment(state,{ruleId,source:suggestion?'system':'manual',suggestionKey:suggestion?.key||'',triggerReason:suggestion?.reason||'',triggerRelatedIds:suggestion?.relatedIds||[],primaryBatchId:val('mLawBatch'),subjectId:val('mLawSubject'),role:val('mLawRole'),behaviorDate:val('mLawDate')});state.view='law';return true;});
  }
  function goLawRequirementToRecord(a,req){
    const target=req.target||'event', section={subject:'known-subjects',batch:'known-batches',producer:'known-batches',environment:'known-environment',event:'known-events',flow:'known-flows',document:'known-documents',place:'known-events',vehicle:'known-events'}[target]||'known-events';
    state.law.navHint={text:`${a.direction}｜${req.label}`,target,assessmentId:a.id,requirementId:req.id};state.entryMode='known';state.view='known';render();setTimeout(()=>document.getElementById(section)?.scrollIntoView({behavior:'smooth',block:'start'}),0);
  }
  function bindLawView(){
    document.querySelectorAll('[data-law-dismiss]').forEach(b=>b.onclick=()=>{if(!state.law.dismissedSuggestionKeys.includes(b.dataset.lawDismiss))state.law.dismissedSuggestionKeys.push(b.dataset.lawDismiss);render();});
    document.querySelectorAll('[data-law-start]').forEach(b=>b.onclick=()=>{const h=L.detectDirections(state).find(x=>x.key===b.dataset.lawStart);if(h)lawCreateDialog(h);});
    document.querySelectorAll('[data-law-delete]').forEach(b=>b.onclick=()=>{if(confirm('刪除此法規查核？原始事實不會刪除。')){state.assessments=state.assessments.filter(x=>x.id!==b.dataset.lawDelete);render();}});
    document.querySelectorAll('[data-law-core]').forEach(el=>el.onchange=()=>{const a=state.assessments.find(x=>x.id===el.dataset.id);if(!a)return;const k=el.dataset.lawCore;if(k==='batch')a.primaryBatchId=el.value;if(k==='subject')a.subjectId=el.value;if(k==='role')a.role=el.value;if(k==='date')a.behaviorDate=el.value;L.refreshAssessment(state,a);render();});
    document.querySelectorAll('[data-law-progress]').forEach(el=>el.onchange=()=>{L.setProgress(state,el.dataset.lawProgress,el.value);render();});
    document.querySelectorAll('[data-law-pause]').forEach(el=>el.onchange=()=>{const a=state.assessments.find(x=>x.id===el.dataset.lawPause);if(a)a.pauseReason=el.value;});
    document.querySelectorAll('[data-law-notes]').forEach(el=>el.onchange=()=>{const a=state.assessments.find(x=>x.id===el.dataset.lawNotes);if(a)a.notes=el.value;});
    document.querySelectorAll('[data-law-req-state]').forEach(el=>el.onchange=()=>{L.setRequirementState(state,el.dataset.lawReqState,el.dataset.req,el.value||'尚有要件待確認');render();});
    document.querySelectorAll('[data-law-link]').forEach(b=>b.onclick=()=>{const select=document.getElementById(`lawCand-${b.dataset.lawLink}-${b.dataset.req}`),recordId=select?.value;if(!recordId){alert('請先選擇候選資料。');return;}L.addEvidenceLink(state,b.dataset.lawLink,b.dataset.req,recordId,b.dataset.side);render();});
    document.querySelectorAll('[data-law-unlink]').forEach(b=>b.onclick=()=>{L.removeEvidenceLink(state,b.dataset.lawUnlink,b.dataset.req,b.dataset.record,b.dataset.side);render();});
    document.querySelectorAll('[data-law-goto]').forEach(b=>b.onclick=()=>{const a=state.assessments.find(x=>x.id===b.dataset.lawGoto);if(!a)return;const {requirements}=L.getRequirements(state,a),req=requirements.find(x=>x.id===b.dataset.req);if(req)goLawRequirementToRecord(a,req);});
  }
  function renderLawSummaryBlock(){
    const snap=L.lawSnapshot(state), suggestions=snap.suggestions.filter(x=>!state.assessments.some(a=>a.suggestionKey===x.key));
    return `<section class="card"><div class="record-head"><div><h3>可能法規方向／後續查核</h3><p class="muted">與已確認事實分開呈現；不會寫入下方稽查紀錄敘述草稿。</p></div><button class="secondary" data-open-law>查看法規導航</button></div>${state.assessments.length?state.assessments.map(a=>{const {requirements,resolved}=L.getRequirements(state,a),pending=requirements.filter(r=>r.required&&['尚有要件待確認','本次未查'].includes(a.requirementStates?.[r.id]||'尚有要件待確認'));return `<div class="subcard"><strong>${esc(a.direction)}</strong>｜${esc(a.legalState)}<div class="muted">${esc(batchName(a.primaryBatchId)||'未指定批次')}｜${esc(subjName(a.subjectId)||'未指定主體')} ${a.role?`｜${esc(a.role)}`:''}</div>${resolved.status!=='ok'?`<div class="muted">${esc(resolved.message)}</div>`:''}${pending.length?`<div class="muted">尚待確認：${pending.map(x=>esc(x.label)).join('、')}</div>`:'<div class="muted">目前沒有未處理的必要要件。</div>'}${a.progress==='暫不深入'?`<div class="muted">本次暫不深入${a.pauseReason?`：${esc(a.pauseReason)}`:''}</div>`:''}</div>`;}).join(''):'<div class="empty compact">尚未建立正式法規查核。</div>'}${suggestions.length?`<div class="notice info compact">另有 ${suggestions.length} 個系統可能方向尚未展開：${suggestions.map(x=>esc(x.title)).join('、')}</div>`:''}</section>`;
  }

  function renderSubjects(){if(!state.subjects.length)return '<div class="empty">尚未建立主體。</div>';return state.subjects.map(s=>{const linked=state.places.filter(p=>p.subjectId===s.id);return `<article class="subcard"><div class="record-head"><div><h4>${esc(s.name||s.id)}</h4><div class="chips"><span class="chip blue">${esc(s.kind)}</span>${s.roles.map(r=>`<span class="chip">${esc(r)}</span>`).join('')}</div></div><button class="danger" data-del="subject" data-id="${s.id}">刪除</button></div>${s.identitySource?`<div class="muted">身分資料來源：${esc(s.identitySource)}</div>`:''}${linked.length?`<div class="muted">關聯地點：${linked.map(p=>esc(p.name||p.id)).join('、')}</div>`:''}${s.notes?`<div>${esc(s.notes)}</div>`:''}</article>`;}).join('');}
  function renderBatchesCompact(){if(!state.batches.length)return '<div class="empty">尚未建立物質批次。</div>';return state.batches.map(b=>`<article class="subcard"><div class="record-head"><div><h4>${esc(b.label||b.id)}</h4><div class="chips"><span class="chip blue">${esc(b.materialKind||'未辨識')}</span>${b.quantity?`<span class="chip">${esc(b.quantity)} ${esc(b.quantityUnit)}</span>`:''}${b.classification?`<span class="chip">${esc(b.classification)}</span>`:''}${b.sourceStatus?`<span class="chip warn">${esc(b.sourceStatus)}</span>`:''}${b.reviewRequired?'<span class="chip warn">相關研判需重新確認</span>':''}</div></div><div class="btn-row"><button class="secondary" data-add-producer="${b.id}">＋產生者</button><button class="secondary" data-edit="batch" data-id="${b.id}">編輯批次</button><button class="danger" data-del="batch" data-id="${b.id}">刪除</button></div></div>${b.appearance?`<div>${esc(b.appearance)}</div>`:''}${renderProducerRelations(b.id,true)}${renderHistory(b)}</article>`).join('');}
  function renderBatchesFull(){if(!state.batches.length)return '<div class="empty">尚未建立物質批次。</div>';return state.batches.map(b=>`<article class="subcard"><div class="record-head"><div><h4>${esc(b.label||b.id)}</h4><div class="chips"><span class="chip blue">${esc(b.materialKind||'未辨識')}</span><span class="chip ${b.wasteIdentity==='已有事實支持'?'good':'warn'}">認廢：${esc(b.wasteIdentity||'未確認')}</span><span class="chip ${b.classification&& !['尚待確認','無法確認'].includes(b.classification)?'good':'warn'}">分類：${esc(b.classification||'尚未確認')}</span>${b.detailClassification?`<span class="chip">細分：${esc(b.detailClassification)}</span>`:''}${b.reviewRequired?'<span class="chip warn">相關研判需重新確認</span>':''}</div></div><div class="btn-row"><button data-add-producer="${b.id}">＋產生者／產生來源</button><button class="secondary" data-edit="batch" data-id="${b.id}">編輯批次</button>${b.reviewRequired?`<button class="ghost" data-clear-review="${b.id}">已重新確認</button>`:''}<button class="danger" data-del="batch" data-id="${b.id}">刪除</button></div></div><table class="table"><tr><th>產生活動／情境</th><td>${esc(b.generationContext||b.process||'未填')}</td></tr><tr><th>產生者／產生來源</th><td>${renderProducerRelations(b.id)}</td></tr><tr><th>代碼</th><td>${esc(b.wasteCode||'未核對')} ${b.codeReview?`（${esc(b.codeReview)}）`:''}</td></tr><tr><th>用途</th><td>聲稱：${esc(b.claimUse||'未填')}｜文件：${esc(b.documentUse||'未填')}｜實際：${esc(b.actualUse||'未填')}</td></tr></table>${b.notes?`<div class="muted">${esc(b.notes)}</div>`:''}${renderHistory(b)}</article>`).join('');}
  function producerRelationLabel(r){const subj=subjName(r.subjectId)||r.basisText||'產生者未命名';const place=placeName(r.placeId);return `${subj}${place?`｜${place}`:''}`;}
  function renderProducerRelations(batchId,compact=false){const list=M.producerRelationsForBatch(state,batchId);if(!list.length)return compact?'<div class="muted small">產生者／產生來源：尚未建立</div>':'<div class="empty compact">尚未建立產生者／產生來源關係。</div>';return `<div class="producer-relations">${list.map(r=>`<div class="subcard compact"><div class="record-head"><div><strong>${esc(producerRelationLabel(r))}</strong><div class="chips"><span class="chip ${r.status==='已確認產生者'?'good':r.status==='已排除'?'':'warn'}">${esc(r.status)}</span>${r.evidence?`<span class="chip">${esc(r.evidence)}</span>`:''}</div></div><div class="btn-row"><button class="secondary" data-edit-producer="${r.id}">修正</button>${r.status!=='已排除'?`<button class="ghost" data-exclude-producer="${r.id}">標記排除</button>`:''}</div></div>${r.generationActivity?`<div>產生情境：${esc(r.generationActivity)}</div>`:''}${r.basisText?`<div class="muted">依據／線索：${esc(r.basisText)}</div>`:''}${r.notes?`<div class="muted">${esc(r.notes)}</div>`:''}${renderHistory(r)}</div>`).join('')}</div>`;}
  function renderEnvironmentObservations(){if(!state.environmentObservations.length)return '<div class="empty">尚未建立環境觀察。即使來源、行為人或物質批次未知，也可以先記環境現象。</div>';return state.environmentObservations.map(o=>{const batches=(o.batchIds||[]).map(batchName).filter(Boolean);const leads=(o.sourceLeadIds||[]).map(id=>(state.sourceTrace.checks||[]).find(x=>x.id===id)).filter(Boolean);return `<article class="subcard"><div class="record-head"><div><h4>${esc(M.environmentObservationSummary(state,o))}</h4><div class="chips"><span class="chip blue">${esc(o.evidence||'資料來源未填')}</span>${o.currentStatus?`<span class="chip ${o.currentStatus==='當下持續中'?'warn':''}">${esc(o.currentStatus)}</span>`:''}</div></div><div class="btn-row"><button class="secondary" data-env-follow="${o.id}">＋後續觀察</button><button class="secondary" data-edit-env="${o.id}">修正紀錄</button><button class="danger" data-del="environment" data-id="${o.id}">刪除</button></div></div>${o.phenomena?.length?`<div><strong>現象：</strong>${o.phenomena.map(esc).join('、')}</div>`:''}${o.media?.length?`<div><strong>受影響位置／介質：</strong>${o.media.map(esc).join('、')}</div>`:''}${o.extentText?`<div><strong>範圍／程度：</strong>${esc(o.extentText)}${o.extentBasis?`（${esc(o.extentBasis)}）`:''}</div>`:''}${batches.length?`<div class="muted">關聯批次：${batches.map(esc).join('、')}</div>`:''}${o.sourceDetail?`<div class="muted">來源補充：${esc(o.sourceDetail)}</div>`:''}${leads.length?`<div class="muted">來源線索：${leads.map(x=>esc(x.text)).join('、')}</div>`:''}${o.notes?`<div class="muted">${esc(o.notes)}</div>`:''}${renderHistory(o)}</article>`;}).join('');}
  function renderEnvironmentReview(){const r=state.environmentReview||{};return `<details class="subcard environment-review"><summary><strong>環境影響研判／總覽</strong>｜${esc(r.state||'本次未查')}</summary><p class="muted">只彙整既有環境觀察，不重複輸入散落、滲出、惡臭等現象；也不等同法律上的「污染環境」成立。</p><label class="field"><span class="label">目前研判</span><select id="environmentReviewState">${options(M.environmentReviewStates,r.state||'本次未查')}</select></label><label class="field"><span class="label">引用環境觀察</span>${checks('environmentReviewObs',state.environmentObservations.map(o=>[o.id,M.environmentObservationSummary(state,o)]),r.observationIds||[])}</label><label class="field"><span class="label">補充</span><textarea id="environmentReviewNotes">${esc(r.notes||'')}</textarea></label><div class="btn-row"><button class="secondary" id="saveEnvironmentReview">更新環境影響總覽</button></div></details>`;}
  function bindEnvironmentReview(){document.getElementById('saveEnvironmentReview')?.addEventListener('click',()=>{state.environmentReview={state:val('environmentReviewState')||'本次未查',observationIds:checked('environmentReviewObs'),notes:val('environmentReviewNotes')};render();});}
  function renderSourceLeads(){const list=(state.sourceTrace.checks||[]).filter(x=>x.type==='來源線索');if(!list.length)return '';return `<div class="divider"></div><h4>由環境觀察帶入的可能來源線索</h4>${list.map(x=>`<div class="subcard compact"><div class="record-head"><div><strong>${esc(x.text||'未填線索')}</strong><div class="muted">狀態：${esc(x.status||'待查證')}</div></div><button class="danger" data-del="sourcelead" data-id="${x.id}">刪除</button></div></div>`).join('')}`;}
  function renderCrossModuleHints(){const hints=M.detectCrossModuleHints(state);if(!hints.length)return '';return `<div class="cross-module-hints"><h4>可能涉及其他查核模組</h4><p class="muted">依「現象＋受影響位置／介質＋當下狀態」組合提示，只做導流，不代表法規適用或違規成立。</p>${hints.map(h=>{const d=state.crossModule.dispositions?.[h.key]||{status:'尚未處理',reason:''};return `<div class="subcard compact"><div class="record-head"><div><strong>${esc(h.title)}</strong><div class="muted">${esc(h.reason)}</div><div class="muted">處置：${esc(d.status)}${d.reason?`｜${esc(d.reason)}`:''}</div></div><div class="btn-row"><button class="secondary" data-cross-status="進入查核" data-cross-key="${esc(h.key)}">進入查核</button><button class="ghost" data-cross-status="暫不處理" data-cross-key="${esc(h.key)}">暫不處理</button><button class="ghost" data-cross-status="不適用" data-cross-key="${esc(h.key)}">不適用</button></div></div></div>`;}).join('')}<div class="hint">此獨立廢棄物測試包先記錄導流處置；整合版再連接水污／空污模組。</div></div>`;}
  function bindCrossModuleHints(){document.querySelectorAll('[data-cross-status]').forEach(b=>b.onclick=()=>{const status=b.dataset.crossStatus,key=b.dataset.crossKey;let reason='';if(status!=='進入查核')reason=prompt('可填寫簡短理由（選填）：','')||'';M.setCrossModuleDisposition(state,key,status,reason);render();});}
  function renderVehicles(){if(!state.vehicles.length)return '<div class="empty compact">尚未建立車輛。</div>';return state.vehicles.map(v=>`<article class="subcard compact"><div class="record-head"><div><strong>${esc(v.plate||v.id)}</strong>${v.vehicleType?`｜${esc(v.vehicleType)}`:''}<div class="muted">${v.ownerText?`車主／所屬：${esc(v.ownerText)}　`:''}${v.marking?`車身標示：${esc(v.marking)}　`:''}${v.source?`來源：${esc(v.source)}`:''}</div></div><div class="btn-row"><button class="secondary" data-edit="vehicle" data-id="${v.id}">編輯</button><button class="danger" data-del="vehicle" data-id="${v.id}">刪除</button></div></div>${renderHistory(v)}</article>`).join('');}
  function renderPlaces(){if(!state.places.length)return '<div class="empty compact">尚未建立地點。</div>';return state.places.map(p=>`<article class="subcard compact"><div class="record-head"><div><strong>${esc(p.name||p.id)}</strong><div class="muted">${p.address?esc(p.address):'位置未填'}${p.roles?.length?`｜${p.roles.map(esc).join('、')}`:''}</div>${p.subjectId?`<div class="muted">關聯主體：${esc(subjName(p.subjectId)||'未命名主體')}</div>`:''}${p.landRelation?`<div>${esc(p.landRelation)}</div>`:''}</div><div class="btn-row"><button class="secondary" data-edit="place" data-id="${p.id}">編輯</button><button class="danger" data-del="place" data-id="${p.id}">刪除</button></div></div>${renderHistory(p)}</article>`).join('');}
  function renderEventEntities(){return `<div class="grid2 entity-lists"><div><h4>已建立車輛</h4>${renderVehicles()}</div><div><h4>已建立地點</h4>${renderPlaces()}</div></div><div class="divider"></div>`;}

  function renderTimeline(){const list=M.sortedTimeline(state);if(!list.length)return '<div class="empty">尚未建立事件。</div>';return `<div class="timeline">${list.map(e=>`<div class="timeline-item"><div class="record-head"><div><strong>${esc(e.time||'時間未填')}</strong>｜${esc(e.action||'動作未填')} <span class="chip">${esc(e.eventType)}</span></div><button class="danger" data-del="event" data-id="${e.id}">刪除</button></div><div>${esc(M.eventSummary(state,e))}</div><div class="muted">資料來源：${esc(e.evidence||'未填')}</div></div>`).join('')}</div>`;}
  function renderFlows(){if(!state.flows.length)return '<div class="empty">尚未建立流向。</div>';return state.flows.map(f=>`<article class="subcard"><div class="record-head"><div><h4>${esc(batchName(f.batchId)||f.batchId||'未選批次')}</h4><div>${esc(placeFlowName(f.fromPlaceId)||'？')} → ${esc(placeFlowName(f.toPlaceId)||'？')}</div></div><button class="danger" data-del="flow" data-id="${f.id}">刪除</button></div><div class="chips"><span class="chip">清運：${esc(subjName(f.carrierSubjectId)||'未確認')}</span><span class="chip">車輛：${esc(vehName(f.vehicleId)||'未確認')}</span><span class="chip warn">狀態：${esc(f.status)}</span></div><div class="muted">用途｜聲稱：${esc(f.claimUse||'未填')}｜文件：${esc(f.documentUse||'未填')}｜實際：${esc(f.actualUse||'未填')}</div></article>`).join('');}
  function relatedRefLabel(id){
    const groups=[[state.batches,'批次',['label','materialKind']],[state.producerRelations||[],'產生者關係',['id']],[state.environmentObservations||[],'環境觀察',['id']],[state.events,'事件',['id']],[state.subjects,'主體',['name']],[state.places,'地點',['name']],[state.vehicles,'車輛',['plate']],[state.documents,'文件',['title','type']],[state.flows,'流向',['id']]];
    for(const [list,prefix,keys] of groups){const label=M.labelById(list,id,keys);if(label)return `${prefix}：${label}`;}
    return id||'';
  }
  function renderRelatedIds(item){const ids=Array.isArray(item?.relatedIds)?item.relatedIds.filter(Boolean):[];if(!ids.length)return '';return `<div class="muted small">關聯：${ids.map(x=>esc(relatedRefLabel(x))).join('｜')}</div>`;}

  function renderDocuments(){if(!state.documents.length)return '<div class="empty">尚未記錄外部資料／文件核對。</div>';return state.documents.map(d=>`<article class="subcard"><div class="record-head"><div><h4>${esc(d.type||'核對資料')}｜${esc(d.title||'')}</h4><div class="chips"><span class="chip">來源：${esc(d.sourceType||'未填')}</span><span class="chip ${d.reviewState==='相符'?'good':d.reviewState==='有疑點'?'warn':''}">${esc(d.reviewState)}</span></div></div><button class="danger" data-del="document" data-id="${d.id}">刪除</button></div>${d.recordedContent?`<div><strong>文件記載：</strong>${esc(d.recordedContent)}</div>`:''}${d.reviewIssue?`<div><strong>核對疑點：</strong>${esc(d.reviewIssue)}</div>`:''}</article>`).join('');}
  function renderDoubts(){if(!state.doubts.length)return '<div class="empty">尚無正式疑點。</div>';return state.doubts.map(x=>`<div class="subcard"><div class="record-head"><div><strong>${esc(x.type)}</strong>｜${esc(x.status)}</div><button class="danger" data-del="doubt" data-id="${x.id}">刪除</button></div><div>${esc(x.text)}</div>${renderRelatedIds(x)}${x.sourceReason?`<div class="muted small">建立依據：${esc(x.sourceReason)}</div>`:''}${x.result?`<div class="muted">查證結果：${esc(x.result)}</div>`:''}</div>`).join('');}
  function renderPending(){if(!state.questions.length)return '<div class="empty">尚無待確認事項。</div>';return state.questions.map(x=>`<div class="subcard"><div class="record-head"><div><strong>${esc(x.type)}</strong>｜${esc(x.status)}</div><button class="danger" data-del="pending" data-id="${x.id}">刪除</button></div><div>${esc(x.text)}</div>${renderRelatedIds(x)}${x.sourceReason?`<div class="muted small">建立依據：${esc(x.sourceReason)}</div>`:''}${x.result?`<div class="muted">結果：${esc(x.result)}</div>`:''}</div>`).join('');}

  function renderSystemHints(){const hints=M.detectHints(state);if(!hints.length)return '';return `<section class="card"><h3>系統提示（不是案件資料）</h3><p class="muted">系統只依已輸入客觀事實提示可能需要看的方向。你沒有採用前，不會進摘要或法律研判。</p>${hints.map(h=>`<div class="subcard"><div class="record-head"><div><strong>${esc(h.title)}</strong><div class="muted">提示原因：${esc(h.reason)}</div></div><button class="ghost" data-hint-ignore="${esc(h.key)}">忽略</button></div><div class="btn-row"><button class="secondary" data-hint-pending="${esc(h.key)}" data-title="${esc(h.title)}">加入待確認</button><button data-hint-doubt="${esc(h.key)}" data-title="${esc(h.title)}">建立疑點</button></div></div>`).join('')}</section>`;}
  function renderGapHints(){const gaps=M.detectGaps(state).filter(g=>!state.questions.some(q=>q.createdFromKey===g.key));if(!gaps.length)return '';return `<section class="card"><h3>查漏提示</h3><p class="muted">只提示資料斷點，由稽查員決定要不要新增事件或待確認事項；加入時會保留對應批次／流向關聯。</p>${gaps.map(g=>`<div class="subcard"><strong>${esc(g.text)}</strong><div class="btn-row"><button class="secondary" data-gap-pending="${esc(g.key)}" data-type="${esc(g.type)}" data-text="${esc(g.text)}">加入待確認</button></div></div>`).join('')}</section>`;}

  function hintRecordType(direction){return ({'來源':'來源','認廢':'物質性質','清除':'流向','回填':'用途','處理':'用途','再利用':'再利用用途','第11條':'來源'})[direction]||'其他';}
  function hintRelatedIds(h){const ids=[];if(h?.batchId){ids.push(h.batchId);state.events.filter(e=>e.batchId===h.batchId).forEach(e=>ids.push(e.id));}return [...new Set(ids.filter(Boolean))];}
  function bindHintButtons(){
    document.querySelectorAll('[data-hint-ignore]').forEach(b=>b.onclick=()=>{state.hintsDismissed.push(b.dataset.hintIgnore);render();});
    document.querySelectorAll('[data-hint-pending]').forEach(b=>b.onclick=()=>{const h=M.detectHints(state).find(x=>x.key===b.dataset.hintPending);if(!h)return;M.addPending(state,{type:hintRecordType(h.direction),text:h.title,relatedIds:hintRelatedIds(h),createdFrom:'system-hint',createdFromKey:h.key,sourceReason:h.reason});state.hintsDismissed.push(h.key);render();});
    document.querySelectorAll('[data-hint-doubt]').forEach(b=>b.onclick=()=>{const h=M.detectHints(state).find(x=>x.key===b.dataset.hintDoubt);if(!h)return;M.addDoubt(state,{type:hintRecordType(h.direction),text:h.title,status:'待釐清',relatedIds:hintRelatedIds(h),createdFrom:'system-hint',createdFromKey:h.key,sourceReason:h.reason});state.hintsDismissed.push(h.key);render();});
  }
  function bindGapButtons(){document.querySelectorAll('[data-gap-pending]').forEach(b=>b.onclick=()=>{const g=M.detectGaps(state).find(x=>x.key===b.dataset.gapPending);if(!g)return;M.addPending(state,{type:g.type,text:g.text,relatedIds:g.relatedIds||[],createdFrom:'gap-hint',createdFromKey:g.key,sourceReason:'系統查漏提示'});render();});}
  function bindRecordButtons(){
    document.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{const map={subject:'subjects',vehicle:'vehicles',place:'places',batch:'batches',producer:'producerRelations',environment:'environmentObservations',event:'events',document:'documents',flow:'flows',pending:'questions',doubt:'doubts'};if(b.dataset.del==='sourcelead'){state.sourceTrace.checks=(state.sourceTrace.checks||[]).filter(x=>x.id!==b.dataset.id);state.environmentObservations.forEach(o=>o.sourceLeadIds=(o.sourceLeadIds||[]).filter(id=>id!==b.dataset.id));render();return;}const key=map[b.dataset.del];if(!key)return;state[key]=state[key].filter(x=>x.id!==b.dataset.id);if(key==='environmentObservations')state.environmentReview.observationIds=(state.environmentReview.observationIds||[]).filter(id=>id!==b.dataset.id);render();});
    document.querySelectorAll('[data-edit="batch"]').forEach(b=>b.onclick=()=>batchDialog(b.dataset.id));
    document.querySelectorAll('[data-edit="vehicle"]').forEach(b=>b.onclick=()=>vehicleDialog(b.dataset.id));
    document.querySelectorAll('[data-edit="place"]').forEach(b=>b.onclick=()=>placeDialog(b.dataset.id));
    document.querySelectorAll('[data-add-producer]').forEach(b=>b.onclick=()=>producerRelationDialog(b.dataset.addProducer));
    document.querySelectorAll('[data-edit-producer]').forEach(b=>b.onclick=()=>{const r=state.producerRelations.find(x=>x.id===b.dataset.editProducer);if(r)producerRelationDialog(r.batchId,r.id);});document.querySelectorAll('[data-exclude-producer]').forEach(b=>b.onclick=()=>{const r=state.producerRelations.find(x=>x.id===b.dataset.excludeProducer);if(!r)return;M.updateProducerRelation(state,r.id,{status:'已排除',notes:[r.notes,'查證後排除本候選產生者。'].filter(Boolean).join('；')});render();});
    document.querySelectorAll('[data-edit-env]').forEach(b=>b.onclick=()=>environmentObservationDialog(b.dataset.editEnv));
    document.querySelectorAll('[data-env-follow]').forEach(b=>b.onclick=()=>environmentObservationDialog('',b.dataset.envFollow));
    document.querySelectorAll('[data-clear-review]').forEach(b=>b.onclick=()=>{const batch=state.batches.find(x=>x.id===b.dataset.clearReview);if(batch)batch.reviewRequired=false;render();});
  }

  function dialogShell(title,body,onSave){
    const old=document.getElementById('modalLayer');old?.remove();
    const layer=document.createElement('div');layer.id='modalLayer';layer.style='position:fixed;inset:0;background:rgba(16,50,92,.35);z-index:100;display:grid;place-items:center;padding:14px;overflow:auto';
    layer.innerHTML=`<div class="card" style="width:min(760px,100%);max-height:92vh;overflow:auto;margin:auto"><div class="record-head"><h3>${esc(title)}</h3><button class="ghost" id="modalClose">關閉</button></div>${body}<div class="btn-row end"><button id="modalSave">儲存</button></div></div>`;
    document.body.appendChild(layer);document.getElementById('modalClose').onclick=()=>layer.remove();document.getElementById('modalSave').onclick=()=>{if(onSave()!==false){layer.remove();render();}};
  }
  function subjectDialog(onCreated){dialogShell('新增主體',`<label class="field"><span class="label">姓名／事業名稱</span><input id="mName"></label><label class="field"><span class="label">主體類型</span><select id="mKind">${options(['人員','事業／公司','土地關係人','其他'],'','請選擇')}</select></label><label class="field"><span class="label">本案角色（可複選）</span>${checks('mRoles',M.roles,[])}</label><label class="field"><span class="label">身分資料來源</span><select id="mIdentity">${options(M.evidenceTypes)}</select></label><label class="field"><span class="label">補充</span><textarea id="mNotes"></textarea></label><details class="subcard"><summary><strong>同時建立這個主體的本案相關地點（選填）</strong></summary><p class="muted">例如「甲營造」的「A 工地」。主體與地點仍是兩筆資料，只是一次建立關聯。</p><label class="field"><span class="label">地點名稱／代稱</span><input id="mSubjectPlaceName" placeholder="例如：A 工地"></label><label class="field"><span class="label">地址／位置</span><input id="mSubjectPlaceAddress"></label><label class="field"><span class="label">地點角色</span>${checks('mSubjectPlaceRoles',['原始產生地','裝載地','暫存地','中轉地','卸載地','堆置地','回填地','處理場所','再利用場所','最終去向','其他'],[])}</label></details>`,()=>{const subject=M.addSubject(state,{name:val('mName')||'未命名主體',kind:val('mKind')||'其他',roles:checked('mRoles'),identitySource:val('mIdentity'),notes:val('mNotes')});const placeNameValue=val('mSubjectPlaceName'),placeAddress=val('mSubjectPlaceAddress');if(placeNameValue||placeAddress)M.addPlace(state,{name:placeNameValue||`${subject.name}相關地點`,address:placeAddress,roles:checked('mSubjectPlaceRoles'),subjectId:subject.id,notes:'由新增主體時一併建立'});onCreated?.(subject);});}

  function batchDialog(batchId=''){
    const b=state.batches.find(x=>x.id===batchId)||null;
    const titleText=b?'編輯物質批次':'新增物質批次';
    dialogShell(titleText,`<div class="notice info">物質／廢棄物事實與環境觀察分開；一般／事業分類主要依「產生者＋產生情境」確認。產生者關係請在批次儲存後另行建立，可同時保留多個候選。</div><label class="field"><span class="label">批次名稱／現場代稱</span><input id="mBatchLabel" value="${esc(b?.label||'')}" placeholder="例如：A 區混合物"></label><label class="field"><span class="label">現場可辨識物質</span><select id="mMaterial">${options(M.materialKinds,b?.materialKind||'')}</select></label><label class="field"><span class="label">外觀／狀態</span><input id="mAppearance" value="${esc(b?.appearance||'')}" placeholder="顏色、混合、包裝等"></label><div class="grid2"><label class="field"><span class="label">約略數量</span><input id="mQty" value="${esc(b?.quantity||'')}"></label><label class="field"><span class="label">單位</span><select id="mQtyUnit">${options(['噸','公斤','立方公尺','袋','桶','車次','約估／其他'],b?.quantityUnit||'')}</select></label></div><label class="field"><span class="label">數量資料來源</span><select id="mQtySource">${options(['現場估算','磅單','業者陳述','申報資料','其他文件','無法估算'],b?.quantitySource||'')}</select></label><label class="field"><span class="label">廢棄物身分狀態</span><select id="mWasteIdentity">${options(M.wasteIdentityStates,b?.wasteIdentity||'')}</select><span class="hint">尚未查清可保留「尚有要件待確認」或「無法確認」；不會阻止繼續記行為、來源與流向。</span></label><label class="field"><span class="label">來源狀態</span><select id="mBatchSource">${options(M.sourceStates,b?.sourceStatus||'')}</select></label><div class="grid2"><label class="field"><span class="label">產生活動／情境</span><input id="mGenerationContext" value="${esc(b?.generationContext||b?.process||'')}" placeholder="例如：家戶生活、住家裝修、製程、營建作業等"></label><label class="field"><span class="label">廢棄物分類</span><select id="mClass">${options(M.classificationOptions,b?.classification||'')}</select><span class="hint">一般／事業的分水嶺以產生者及產生情境為主要事實基礎。</span></label></div><label class="field"><span class="label">細部分類／其他管理身分（選填）</span><select id="mDetailClass">${options(M.detailClassificationOptions,b?.detailClassification||'','尚未細分')}</select></label><div class="grid2"><label class="field"><span class="label">廢棄物代碼（後段核對）</span><input id="mWasteCode" value="${esc(b?.wasteCode||'')}"></label><label class="field"><span class="label">代碼核對</span><select id="mCodeReview">${options(M.reviewStates,b?.codeReview||'')}</select></label></div><div class="grid3"><label class="field"><span class="label">聲稱用途</span><select id="mClaimUse">${options(M.useOptions,b?.claimUse||'')}</select></label><label class="field"><span class="label">文件用途</span><select id="mDocUse">${options(M.useOptions,b?.documentUse||'')}</select></label><label class="field"><span class="label">實際用途</span><select id="mActualUse">${options(M.useOptions,b?.actualUse||'')}</select></label></div><label class="field"><span class="label">補充</span><textarea id="mNotes">${esc(b?.notes||'')}</textarea></label>${b?.reviewRequired?'<div class="notice warn">此批次先前已修正既有資料，相關研判需重新確認。</div>':''}`,()=>{const generationContext=val('mGenerationContext');const data={label:val('mBatchLabel')||(b?.label||`批次 ${state.batches.length+1}`),materialKind:val('mMaterial'),appearance:val('mAppearance'),quantity:val('mQty'),quantityUnit:val('mQtyUnit'),quantitySource:val('mQtySource'),wasteIdentity:val('mWasteIdentity'),sourceStatus:val('mBatchSource'),classification:val('mClass'),detailClassification:val('mDetailClass'),generationContext,process:generationContext,wasteCode:val('mWasteCode'),codeReview:val('mCodeReview'),claimUse:val('mClaimUse'),documentUse:val('mDocUse'),actualUse:val('mActualUse'),notes:val('mNotes')};if(b)M.updateBatch(state,b.id,data);else M.addBatch(state,data);});
  }
  function producerRelationDialog(batchId,relationId=''){
    const r=state.producerRelations.find(x=>x.id===relationId)||null;const batch=state.batches.find(x=>x.id===batchId);if(!batch)return;
    dialogShell(r?'修正產生者／產生來源關係':'新增產生者／產生來源關係',`<div class="notice info">「產生者」與實際排出者、搬運者、地主等角色分開。疑似或線索可先保留，不會因此自動確定一般／事業廢棄物分類。</div><label class="field"><span class="label">物質批次</span><input value="${esc(batch.label||batch.id)}" disabled></label><label class="field"><span class="label">候選／已確認產生者</span><select id="mProducerSubject">${options(state.subjects.map(s=>[s.id,s.name]),r?.subjectId||'','尚未建立／無法確認')}</select></label><label class="field"><span class="label">產生來源地點（選填）</span><select id="mProducerPlace">${options(state.places.map(p=>[p.id,placeOptionLabel(p)]),r?.placeId||'','尚未確認')}</select></label><div class="grid2"><label class="field"><span class="label">確認狀態</span><select id="mProducerStatus">${options(M.producerRelationStates,r?.status||'尚待查證')}</select></label><label class="field"><span class="label">資料來源</span><select id="mProducerEvidence">${options(M.evidenceTypes,r?.evidence||'')}</select></label></div><label class="field"><span class="label">產生情境／活動</span><input id="mProducerActivity" value="${esc(r?.generationActivity||batch.generationContext||batch.process||'')}" placeholder="例如：家戶生活、住家裝修、製程、營建作業"></label><label class="field"><span class="label">支持依據／線索</span><textarea id="mProducerBasis" placeholder="例如：當事人陳述、文件、車輛自該處駛出等">${esc(r?.basisText||'')}</textarea></label><label class="field"><span class="label">補充</span><textarea id="mProducerNotes">${esc(r?.notes||'')}</textarea></label>`,()=>{const data={batchId,subjectId:val('mProducerSubject'),placeId:val('mProducerPlace'),status:val('mProducerStatus')||'尚待查證',generationActivity:val('mProducerActivity'),evidence:val('mProducerEvidence'),basisText:val('mProducerBasis'),notes:val('mProducerNotes')};if(!data.subjectId&&!data.basisText&&data.status!=='無法確認'){alert('請至少指定候選產生者，或填寫可追查的產生者線索。');return false;}if(r)M.updateProducerRelation(state,r.id,data);else M.addProducerRelation(state,data);});
  }
  function environmentObservationDialog(observationId='',previousObservationId=''){
    const o=state.environmentObservations.find(x=>x.id===observationId)||null;const prev=state.environmentObservations.find(x=>x.id===previousObservationId)||null;const seed=o||prev||{};const isFollow=!o&&!!prev;
    dialogShell(o?'修正環境觀察':isFollow?'新增後續環境觀察':'新增環境觀察',`<div class="notice info">環境觀察記「發生了什麼」，不是法律上的污染結論。狀態隨時間改變時請用「新增後續觀察」，不要覆蓋原本時點。</div><div class="grid2"><label class="field"><span class="label">記錄／到場時間</span><input id="mEnvRecorded" value="${esc(o?.recordedAt||'')}" placeholder="例如 09/21 10:20"></label><label class="field"><span class="label">現象發生時間／期間</span><input id="mEnvOccurrence" value="${esc(o?.occurrenceTime||'')}" placeholder="非現場所見時尤其要填"></label></div><label class="field"><span class="label">地點物件</span><select id="mEnvPlace">${options(state.places.map(p=>[p.id,placeOptionLabel(p)]),seed.placeId||'','未建立／尚未確認')}</select></label><label class="field"><span class="label">位置文字（地點未建立時可直接描述）</span><input id="mEnvLocationText" value="${esc(o?.locationText||seed.locationText||'')}" placeholder="例如：產業道路北側側溝"></label><label class="field"><span class="label">現象類型（可複選）</span>${checks('mEnvPhenomena',M.environmentPhenomena,o?.phenomena||[])}</label><label class="field"><span class="label">受影響位置／環境介質（可複選）</span>${checks('mEnvMedia',M.environmentMedia,o?.media||seed.media||[])}</label><div class="grid2"><label class="field"><span class="label">範圍／程度</span><input id="mEnvExtent" value="${esc(o?.extentText||'')}" placeholder="例如：約 8×5 公尺／沿側溝約 30 公尺"></label><label class="field"><span class="label">範圍資料性質</span><select id="mEnvExtentBasis">${options(M.environmentExtentBases,o?.extentBasis||'')}</select></label></div><div class="grid2"><label class="field"><span class="label">當下狀態</span><select id="mEnvCurrent">${options(M.environmentCurrentStates,o?.currentStatus||'')}</select></label><label class="field"><span class="label">資料來源</span><select id="mEnvEvidence">${options(M.evidenceTypes,o?.evidence||'現場所見')}</select></label></div><label class="field"><span class="label">資料來源補充</span><input id="mEnvSourceDetail" value="${esc(o?.sourceDetail||'')}" placeholder="例如：監視器 09/20 23:10 畫面"></label><label class="field"><span class="label">關聯物質批次（可複選、可不選）</span>${checks('mEnvBatches',state.batches.map(b=>[b.id,b.label||b.materialKind||b.id]),o?.batchIds||seed.batchIds||[])}</label><label class="field"><span class="label">可能來源線索／追查方向（選填）</span><textarea id="mEnvSourceLead" placeholder="例如：上游排水孔 A；甲工地側門附近。儲存後進既有來源待查結構，不會直接變成來源事實。"></textarea></label><label class="field"><span class="label">補充</span><textarea id="mEnvNotes">${esc(o?.notes||'')}</textarea></label>`,()=>{const phenomena=checked('mEnvPhenomena'),placeId=val('mEnvPlace'),locationText=val('mEnvLocationText');if(!phenomena.length){alert('請至少選擇一個環境現象。');return false;}if(!placeId&&!locationText){alert('請選擇地點或填寫位置描述。');return false;}const data={recordedAt:val('mEnvRecorded'),occurrenceTime:val('mEnvOccurrence'),placeId,locationText,phenomena,media:checked('mEnvMedia'),extentText:val('mEnvExtent'),extentBasis:val('mEnvExtentBasis'),currentStatus:val('mEnvCurrent'),evidence:val('mEnvEvidence')||'現場所見',sourceDetail:val('mEnvSourceDetail'),batchIds:checked('mEnvBatches'),notes:val('mEnvNotes'),previousObservationId:o?.previousObservationId||previousObservationId||''};let saved;if(o){saved=M.updateEnvironmentObservation(state,o.id,data);}else saved=M.addEnvironmentObservation(state,data);const leadText=val('mEnvSourceLead');if(leadText){const lead=M.addSourceLead(state,{text:leadText,status:'待查證',environmentObservationId:saved.id,relatedIds:[saved.id,...(saved.batchIds||[])]});saved.sourceLeadIds=[...(saved.sourceLeadIds||[]),lead.id];if(!state.sourceTrace.status)state.sourceTrace.status='有來源線索，待查證';}return true;});
  }
  function vehicleDialog(vehicleId=''){const v=state.vehicles.find(x=>x.id===vehicleId)||null;dialogShell(v?'編輯車輛':'新增車輛',`<label class="field"><span class="label">車牌</span><input id="mPlate" value="${esc(v?.plate||'')}"></label><label class="field"><span class="label">車種</span><input id="mVehicleType" value="${esc(v?.vehicleType||'')}"></label><label class="field"><span class="label">車主／所屬公司（記載內容）</span><input id="mVehicleOwner" value="${esc(v?.ownerText||'')}"></label><label class="field"><span class="label">車身標示</span><input id="mMarking" value="${esc(v?.marking||'')}"></label><label class="field"><span class="label">資料來源</span><select id="mVehicleSource">${options(M.evidenceTypes,v?.source||'')}</select></label><label class="field"><span class="label">補充</span><textarea id="mVehicleNotes">${esc(v?.notes||'')}</textarea></label>`,()=>{const data={plate:val('mPlate')||(v?.plate||'車牌未確認'),vehicleType:val('mVehicleType'),ownerText:val('mVehicleOwner'),marking:val('mMarking'),source:val('mVehicleSource'),notes:val('mVehicleNotes')};if(v)M.updateVehicle(state,v.id,data);else M.addVehicle(state,data);});}
  function placeDialog(placeId=''){const p=state.places.find(x=>x.id===placeId)||null;dialogShell(p?'編輯地點節點':'新增地點節點',`<label class="field"><span class="label">地點名稱／代稱</span><input id="mPlaceName" value="${esc(p?.name||'')}"></label><label class="field"><span class="label">地址／位置描述</span><input id="mAddress" value="${esc(p?.address||'')}"></label><label class="field"><span class="label">關聯主體（選填）</span><select id="mPlaceSubject">${options(state.subjects.map(s=>[s.id,s.name]),p?.subjectId||'','無關聯／尚未確認')}</select><span class="hint">例如「A 工地」可關聯到「甲營造」。主體與地點仍保持獨立。</span></label><label class="field"><span class="label">地點角色</span>${checks('mPlaceRoles',['原始產生地','裝載地','暫存地','中轉地','卸載地','堆置地','回填地','處理場所','再利用場所','最終去向','其他'],p?.roles||[])}</label><label class="field"><span class="label">土地關係補充</span><textarea id="mLand">${esc(p?.landRelation||'')}</textarea></label><label class="field"><span class="label">其他補充</span><textarea id="mPlaceNotes">${esc(p?.notes||'')}</textarea></label>`,()=>{const data={name:val('mPlaceName')||(p?.name||'未命名地點'),address:val('mAddress'),subjectId:val('mPlaceSubject'),roles:checked('mPlaceRoles'),landRelation:val('mLand'),notes:val('mPlaceNotes')};if(p)M.updatePlace(state,p.id,data);else M.addPlace(state,data);});}

  function nestedDialogShell(title,body,onSave){const old=document.getElementById('subModalLayer');old?.remove();const layer=document.createElement('div');layer.id='subModalLayer';layer.style='position:fixed;inset:0;background:rgba(16,50,92,.28);z-index:130;display:grid;place-items:center;padding:14px;overflow:auto';layer.innerHTML=`<div class="card" style="width:min(680px,100%);max-height:90vh;overflow:auto;margin:auto"><div class="record-head"><h3>${esc(title)}</h3><button class="ghost" id="subModalClose">關閉</button></div>${body}<div class="btn-row end"><button id="subModalSave">新增並帶回</button></div></div>`;document.body.appendChild(layer);document.getElementById('subModalClose').onclick=()=>layer.remove();document.getElementById('subModalSave').onclick=()=>{if(onSave()!==false)layer.remove();};}
  function quickPlaceDialog(defaultRole,onCreated){nestedDialogShell('快速新增地點',`<label class="field"><span class="label">地點名稱／代稱</span><input id="qPlaceName" placeholder="例如：A 工地／產業道路旁空地"></label><label class="field"><span class="label">地址／位置描述</span><input id="qPlaceAddress"></label><label class="field"><span class="label">關聯主體（選填）</span><select id="qPlaceSubject">${options(state.subjects.map(s=>[s.id,s.name]),'','無關聯／尚未確認')}</select></label><label class="field"><span class="label">地點角色</span><select id="qPlaceRole">${options(['原始產生地','裝載地','暫存地','中轉地','卸載地','堆置地','回填地','處理場所','再利用場所','最終去向','其他'],defaultRole||'')}</select></label>`,()=>{const name=val('qPlaceName'),address=val('qPlaceAddress');if(!name&&!address){alert('請至少填寫地點名稱或位置描述。');return false;}const p=M.addPlace(state,{name:name||'未命名地點',address,subjectId:val('qPlaceSubject'),roles:val('qPlaceRole')?[val('qPlaceRole')]:[],notes:'由物流向快速建立'});onCreated?.(p);return true;});}

  function eventDialog(){dialogShell('新增客觀／歷史事件',`<div class="grid2"><label class="field"><span class="label">時間</span><input id="mTime" placeholder="例如 09/21 10:15"></label><label class="field"><span class="label">事件類型</span><select id="mEventType">${options(['當下現場事實','歷史事件','詢問／陳述事件','查證結果'])}</select></label></div><div class="grid2"><label class="field"><span class="label">主體</span><select id="mEventSubject">${options(state.subjects.map(s=>[s.id,s.name]),'','未知／未建立')}</select></label><label class="field"><span class="label">車輛</span><select id="mEventVehicle">${options(state.vehicles.map(v=>[v.id,v.plate]),'','未知／未建立')}</select></label></div><div class="grid2"><label class="field"><span class="label">物質批次</span><select id="mEventBatch">${options(state.batches.map(b=>[b.id,b.label]),'','未知／未建立')}</select></label><label class="field"><span class="label">地點</span><select id="mEventPlace">${options(state.places.map(p=>[p.id,p.name]),'','未知／未建立')}</select></label></div><label class="field"><span class="label">客觀動作</span><select id="mAction">${options(M.objectiveActions)}</select></label><label class="field"><span class="label">內容／陳述原文</span><textarea id="mDescription" placeholder="客觀事件寫所見動作；陳述事件保留誰說了什麼。"></textarea></label><label class="field"><span class="label">資料來源</span><select id="mEvidence">${options(M.evidenceTypes,'現場所見')}</select></label>`,()=>{M.addEvent(state,{time:val('mTime'),eventType:val('mEventType')||'當下現場事實',subjectId:val('mEventSubject'),vehicleId:val('mEventVehicle'),batchId:val('mEventBatch'),placeId:val('mEventPlace'),action:val('mAction'),description:val('mDescription'),evidence:val('mEvidence')||'現場所見'});});}
  function flowDialog(){dialogShell('新增物流向',`<label class="field"><span class="label">物質批次</span><select id="mFlowBatch">${options(state.batches.map(b=>[b.id,b.label]))}</select></label><div class="grid2"><label class="field"><span class="label">本段來源地點</span><select id="mFrom">${options(state.places.map(p=>[p.id,placeOptionLabel(p)]),'','未知')}</select><button type="button" class="secondary inline-add" id="mAddFromPlace">＋新增來源地點</button></label><label class="field"><span class="label">本段去向地點</span><select id="mTo">${options(state.places.map(p=>[p.id,placeOptionLabel(p)]),'','未知')}</select><button type="button" class="secondary inline-add" id="mAddToPlace">＋新增去向地點</button></label></div><div class="notice info">物流向記錄「物從哪裡到哪裡」。公司／人員是主體，不直接當地點；快速新增地點時可順手關聯既有主體。</div><div class="grid2"><label class="field"><span class="label">清運／搬運主體</span><select id="mCarrier">${options(state.subjects.map(s=>[s.id,s.name]),'','未知')}</select></label><label class="field"><span class="label">車輛</span><select id="mFlowVehicle">${options(state.vehicles.map(v=>[v.id,v.plate]),'','未知')}</select></label></div><div class="grid3"><label class="field"><span class="label">聲稱用途</span><select id="mFlowClaim">${options(M.useOptions)}</select></label><label class="field"><span class="label">文件用途</span><select id="mFlowDoc">${options(M.useOptions)}</select></label><label class="field"><span class="label">實際用途</span><select id="mFlowActual">${options(M.useOptions)}</select></label></div><label class="field"><span class="label">流向確認狀態</span><select id="mFlowStatus">${options(['待確認','已有事實支持','無法確認','已確認'])}</select></label><label class="field"><span class="label">資料來源／補充</span><textarea id="mFlowNotes"></textarea></label>`,()=>{M.addFlow(state,{batchId:val('mFlowBatch'),fromPlaceId:val('mFrom'),toPlaceId:val('mTo'),carrierSubjectId:val('mCarrier'),vehicleId:val('mFlowVehicle'),claimUse:val('mFlowClaim'),documentUse:val('mFlowDoc'),actualUse:val('mFlowActual'),status:val('mFlowStatus')||'待確認',notes:val('mFlowNotes')});});const addOption=(selectId,p)=>{const sel=document.getElementById(selectId);if(!sel)return;const opt=document.createElement('option');opt.value=p.id;opt.textContent=placeOptionLabel(p);sel.appendChild(opt);sel.value=p.id;};document.getElementById('mAddFromPlace').onclick=()=>quickPlaceDialog('裝載地',p=>addOption('mFrom',p));document.getElementById('mAddToPlace').onclick=()=>quickPlaceDialog('卸載地',p=>addOption('mTo',p));}

  function documentDialog(){dialogShell('新增外部資料／文件核對',`<div class="grid2"><label class="field"><span class="label">核對類型</span><select id="mDocType">${options(['資格／許可','清理計畫書','申報資料','聯單／清運憑證','契約／委託資料','磅單／收據','其他'])}</select></label><label class="field"><span class="label">資料來源類型</span><select id="mDocSource">${options(['主管機關系統','許可文件','清理計畫書','申報資料','聯單','業者提供文件','其他'])}</select></label></div><label class="field"><span class="label">文件／資料記載內容</span><textarea id="mRecorded"></textarea><span class="hint">文件寫了什麼，和你最後怎麼核對分開保存。</span></label><label class="field"><span class="label">核對結果</span><select id="mReview">${options(M.reviewStates)}</select></label><label class="field"><span class="label">有疑點時的結構化方向</span><select id="mIssue">${options(['實際物質不同','代碼不同','數量不同','車輛不同','清運者不同','去向不同','日期／時間不同','處理／再利用方式不同','資格有效期間有疑點','許可範圍有疑點','現場未提出文件','其他'],'','無／尚未選')}</select></label><div class="grid2"><label class="field"><span class="label">對應批次</span><select id="mDocBatch">${options(state.batches.map(b=>[b.id,b.label]),'','無')}</select></label><label class="field"><span class="label">對應主體</span><select id="mDocSubject">${options(state.subjects.map(s=>[s.id,s.name]),'','無')}</select></label></div><label class="field"><span class="label">補充</span><textarea id="mDocNotes"></textarea></label>`,()=>{M.addDocument(state,{type:val('mDocType'),sourceType:val('mDocSource'),recordedContent:val('mRecorded'),reviewState:val('mReview')||'本次未查',reviewIssue:val('mIssue'),batchId:val('mDocBatch'),subjectId:val('mDocSubject'),notes:val('mDocNotes')});});}
  function doubtDialog(){dialogShell('新增疑點',`<label class="field"><span class="label">疑點類型</span><select id="mDoubtType">${options(['來源','物質性質','流向','文件不一致','資格','土地關係','委託關係','用途','數量','其他'])}</select></label><label class="field"><span class="label">疑點內容</span><textarea id="mDoubtText"></textarea></label><label class="field"><span class="label">狀態</span><select id="mDoubtStatus">${options(['待釐清','查證中','已釐清','無法釐清','建議升格異常','排除'],'待釐清')}</select></label>`,()=>{M.addDoubt(state,{type:val('mDoubtType')||'其他',text:val('mDoubtText'),status:val('mDoubtStatus')||'待釐清'});});}
  function pendingDialog(){dialogShell('新增待確認事項',`<label class="field"><span class="label">類型</span><select id="mPendingType">${options(['來源','行為人','物質性質','廢棄物分類','流向','最終去向','資格','文件','委託關係','土地關係','再利用用途','環境狀態／污染現象','其他'])}</select></label><label class="field"><span class="label">待確認內容</span><textarea id="mPendingText"></textarea></label><label class="field"><span class="label">狀態</span><select id="mPendingStatus">${options(M.pendingStates,'待查')}</select></label>`,()=>{M.addPending(state,{type:val('mPendingType')||'其他',text:val('mPendingText'),status:val('mPendingStatus')||'待查'});});}

  function renderSummary(){
    const s=M.simpleSummary(state), hints=M.detectHints(state), gaps=M.detectGaps(state);if(!state.draftText)state.draftText=M.buildDraft(state);
    app().innerHTML=`<div class="section-title"><div><h2>現場稽查摘要</h2><p>只整理目前已建立的資料；提示仍不算案件事實。任何步驟未完成也可以在此結束本次查核。</p></div><div class="btn-row"><button class="secondary" id="backKnown">返回對象查核</button><button class="secondary" id="backUnknownSummary">返回來源待查</button></div></div>
      <section class="summary-grid"><div class="summary-block"><h4>案件入口</h4>${esc(s.entryMode)}</div><div class="summary-block"><h4>資料量</h4>主體 ${s.subjects}｜批次 ${s.batches}｜環境觀察 ${s.environmentObservations}｜事件 ${s.events}｜流向 ${s.flows}</div><div class="summary-block"><h4>目前疑點</h4>${s.doubts} 項</div><div class="summary-block"><h4>待確認</h4>${s.pending} 項｜物質身分未完整 ${s.unresolvedBatches} 批｜分類待確認 ${s.unresolvedClassification} 批</div></section>
      <section class="card"><h3>環境觀察（客觀事實）</h3>${renderEnvironmentObservations()}${state.environmentReview?.state?`<div class="notice info">環境影響研判／總覽：${esc(state.environmentReview.state)}${state.environmentReview.notes?`｜${esc(state.environmentReview.notes)}`:''}</div>`:''}</section>
      <section class="card"><h3>物質批次與產生者／分類</h3>${renderBatchesFull()}</section>
      <section class="card"><h3>案件時間軸</h3>${renderTimeline()}</section>
      <section class="card"><h3>物流向</h3>${renderFlows()}</section>
      <section class="card"><h3>正式疑點／待確認</h3><div class="grid2"><div>${renderDoubts()}</div><div>${renderPending()}</div></div></section>
      ${hints.length?`<section class="card"><h3>尚未採用的系統提示</h3><p class="muted">共 ${hints.length} 項；不列入正式摘要內容。</p></section>`:''}
      ${gaps.length?`<section class="card"><h3>仍有查漏提示</h3>${gaps.map(g=>`<div class="notice info">${esc(g.text)}</div>`).join('')}</section>`:''}
      ${renderCrossModuleHints()}
      ${renderLawSummaryBlock()}
      ${renderDepartureCheckBlock()}
      <section class="card"><h3>可編輯「稽查紀錄敘述草稿」</h3><p class="muted">只用目前已建立資料組句；不把系統提示自動寫成事實。</p><textarea class="draft" id="draftText">${esc(state.draftText)}</textarea><div class="btn-row"><button id="regenDraft">依目前事實重新產生</button><button class="secondary" id="copyDraft">複製文字</button></div></section>
      ${commonTools()}`;
    document.getElementById('backKnown').onclick=()=>{state.entryMode='known';setView('known');};
    document.getElementById('backUnknownSummary').onclick=()=>{state.entryMode='unknown';setView('unknown');};
    document.getElementById('draftText').oninput=e=>state.draftText=e.target.value;
    document.getElementById('regenDraft').onclick=()=>{state.draftText=M.buildDraft(state);render();};
    document.getElementById('copyDraft').onclick=async()=>{try{await navigator.clipboard.writeText(document.getElementById('draftText').value);alert('已複製');}catch{alert('瀏覽器未允許剪貼簿，請手動全選複製。');}};
    bindRecordButtons();bindCrossModuleHints();bindTools();
  }

  function validateState(input){
    const copy=JSON.parse(JSON.stringify(input||{}));
    if(!M.validateImport(copy))throw new Error('Waste 案件格式或 provenance 不符。');
    M.ensureState(copy);L.ensureState(copy);
    return copy;
  }
  function snapshot(){return JSON.parse(JSON.stringify(state));}
  function restore(input){state=validateState(input);if(!state.view)state.view='home';if(host)render();return snapshot();}
  function reset(){state=M.createState();L.ensureState(state);if(host)render();}
  function mount(el){host=el;host.classList.add('waste-v017-host');render();}
  function unmount(){if(host){host.innerHTML='';host.classList.remove('waste-v017-host');}host=null;}
  root.WasteV1UI=Object.freeze({version:M.VERSION,mount,unmount,hasData,snapshot,restore,reset,validateState});
})(typeof window==='undefined'?globalThis:window);
